// fileBackend.ts -- file-backed JSON config store backend (LOCAL / docker-compose)
//
// Auto-generated by datrix-codegen-typescript. Do not edit manually.
//
// Reads the baked JSON config profile at the path baked into `CONFIG_FILE_PATH`
// at generation time -- the resolved `RuntimeBootstrap.config_file_path` (the
// same mounted-path contract every language's file-engine backend uses; see
// `LOCAL_CONFIG_FILE_PATH` in datrix-common). No environment variable reads, no
// network calls.
//
// The JSON file is expected to be a mapping of profile name to a mapping of
// config key to scalar value:
//
//   {
//     "connections": { "ordersDbHost": "localhost", "ordersDbPort": 5432 },
//     "featureFlags": { "enableCheckout": true }
//   }
//
// The file is re-read from disk on every `fetchProfile` call so config changes
// applied by replacing the mounted JSON file are picked up on the next poll
// interval without restarting the service (parity with the Python file-engine
// backend's re-read-every-call semantics).
//
// Behavior on missing or malformed file: `FileConfigError` is thrown immediately
// (fail-loud). The RemoteConfigClient propagates this according to its
// `failOpen` setting: when `failOpen` is false (the default) the error
// surfaces so the service exits with a clear message; when `failOpen` is true
// the previous cache is retained.

import { existsSync, readFileSync } from 'node:fs';

const CONFIG_FILE_PATH = "/app/config/config-store.json";

/** Thrown when the baked JSON config file cannot be read or is malformed. */
export class FileConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'FileConfigError';
  }
}

/**
 * Read config-store profiles from the baked JSON file at `CONFIG_FILE_PATH`.
 *
 * The file is read fresh on every `fetchProfile` call so rolling updates
 * (replacing the mounted JSON) are visible within one poll interval.
 */
export class FileConfigBackend {
  /**
   * Return the stored scalar values for `profile` keyed by config key name.
   *
   * Returns an empty mapping when the profile is not present in the JSON file
   * (the client falls back to generated defaults for absent keys).
   */
  async fetchProfile(profile: string): Promise<Record<string, unknown>> {
    if (!existsSync(CONFIG_FILE_PATH)) {
      throw new FileConfigError(
        `Config file '${CONFIG_FILE_PATH}' does not exist. Mount the baked ` +
          'JSON config file at the path baked into CONFIG_FILE_PATH before ' +
          'starting the service.',
      );
    }

    let raw: string;
    try {
      raw = readFileSync(CONFIG_FILE_PATH, 'utf-8');
    } catch (err) {
      throw new FileConfigError(
        `Cannot read config file '${CONFIG_FILE_PATH}': ${String(err)}. ` +
          'Verify that the file is readable by the service process.',
      );
    }

    let data: unknown;
    try {
      data = JSON.parse(raw);
    } catch (err) {
      throw new FileConfigError(
        `Config file '${CONFIG_FILE_PATH}' is not valid JSON: ${String(err)}. ` +
          'The file must be a JSON object mapping profile name to key -> scalar value.',
      );
    }

    if (!isRecord(data)) {
      throw new FileConfigError(
        `Config file '${CONFIG_FILE_PATH}' must be a JSON object mapping ` +
          `profile name to key -> scalar value; got ${describeType(data)}.`,
      );
    }

    const profileData: unknown = data[profile] ?? {};
    if (!isRecord(profileData)) {
      throw new FileConfigError(
        `Config file '${CONFIG_FILE_PATH}' profile '${profile}' must be a ` +
          `JSON object of key -> scalar value; got ${describeType(profileData)}.`,
      );
    }

    return { ...profileData };
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function describeType(value: unknown): string {
  return Array.isArray(value) ? 'array' : typeof value;
}
